cards.styles:
.navbar-card {
  --navbar-route-icon-size: 40px;
  --navbar-border-radius: 18px;

  background: linear-gradient(
    315deg,
    rgba(38,72,85,0.96) 0%,
    rgba(15,32,45,0.98) 100%
  ) !important;

  border: 1px solid rgba(140,210,230,0.22) !important;
  border-radius: 18px !important;

  box-shadow:
    0 6px 24px rgba(0,0,0,0.50),
    inset 0 1px 0 rgba(255,255,255,0.06) !important;

  padding: 10px 14px !important;
  gap: 12px !important;
}

/* Botões grandes */
.route .button {
  width: 70px !important;
  min-width: 70px !important;
  height: 60px !important;
  min-height: 60px !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  background: rgba(255,255,255,0.045) !important;
  border: 1px solid rgba(255,255,255,0.09) !important;
  border-radius: 14px !important;
  box-shadow: none !important;

  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease !important;
}

/* Ícones grandes */
.route .icon {
  --mdc-icon-size: 40px !important;
  width: 40px !important;
  height: 40px !important;
}

.route .button:hover {
  background: rgba(255,255,255,0.09) !important;
  border-color: rgba(140,210,230,0.28) !important;
}

.route .button.active {
  background: rgba(101,216,222,0.22) !important;
  border-color: rgba(101,216,222,0.60) !important;
  box-shadow: 0 0 12px rgba(101,216,222,0.12) !important;
  transform: translateY(-2px);
}

/* Esconder os nomes na barra */
.route .label {
  display: none !important;
}

/* Popup Mais */
.navbar-popup {
  background: linear-gradient(
    315deg,
    rgba(38,72,85,0.98) 0%,
    rgba(15,32,45,0.99) 100%
  ) !important;

  backdrop-filter: blur(14px) !important;
  -webkit-backdrop-filter: blur(14px) !important;

  border: 1px solid rgba(140,210,230,0.20) !important;
  border-radius: 16px !important;

  box-shadow:
    0 8px 30px rgba(0,0,0,0.60),
    inset 0 1px 0 rgba(255,255,255,0.06) !important;

  padding: 12px !important;
}

.popup-item .button {
  width: 54px !important;
  height: 54px !important;

  background: rgba(255,255,255,0.055) !important;
  border: 1px solid rgba(140,210,230,0.16) !important;
  border-radius: 12px !important;
  box-shadow: none !important;
}

.popup-item .icon {
  --mdc-icon-size: 30px !important;
  width: 30px !important;
  height: 30px !important;
}

/* Máquina da Louça */
.popup-item:nth-child(1) .icon {
  color: #A78BFA !important;
}

/* Música */
.popup-item:nth-child(2) .icon {
  color: #C8F560 !important;
}

/* Configurações */
.popup-item:nth-child(3) .icon {
  color: #65D8DE !important;
}

/* Programador */
.popup-item:nth-child(4) .icon {
  color: rgba(255,255,255,0.85) !important;
}

.popup-item .label {
  display: block !important;
  color: rgba(255,255,255,0.90) !important;
  background: transparent !important;
  font-size: 13px !important;
  box-shadow: none !important;
}

/* Dar espaço real aos botões grandes */
.route {
  width: 70px !important;
  min-width: 70px !important;
  height: 60px !important;
  min-height: 60px !important;
  flex: 0 0 70px !important;
  overflow: visible !important;
  box-sizing: border-box !important;
}

.route .button {
  width: 70px !important;
  min-width: 70px !important;
  height: 60px !important;
  min-height: 60px !important;
  margin: 0 !important;
  box-sizing: border-box !important;
  overflow: visible !important;
}

/* Mais espaço à volta dos botões */
.navbar-card {
  padding: 14px 18px !important;
  gap: 12px !important;
  overflow: visible !important;
}

.navbar.desktop.bottom {
  overflow: visible !important;
}

